def choose_move(observation):
    # Defensive defaults
    # Prefer staying still if nothing actionable is found
    default_move = (0, 0)

    # Helper to safely get fields
    def get_field(obs, *path, default=None):
        cur = obs
        for p in path:
            if isinstance(cur, dict) and p in cur:
                cur = cur[p]
            else:
                return default
        return cur

    # Attempt common keys across environments
    # 1) resource_collection: look for nearby resources under 'resources' or 'resources_nearby'
    resources = get_field(observation, 'resources', default=None)
    if resources is None:
        resources = get_field(observation, 'resources_nearby', default=None)
    if isinstance(resources, list) and resources:
        # Pick resource with smallest distance if available, else first
        closest = None
        min_dist = float('inf')
        for r in resources:
            if isinstance(r, dict):
                d = r.get('distance')
                if isinstance(d, (int, float)) and d < min_dist:
                    min_dist = d
                    closest = r
        if closest is not None:
            dx = closest.get('dx')
            dy = closest.get('dy')
            if dx in (-1, 0, 1) and dy in (-1, 0, 1):
                return [dx, dy]
            # Fallback: compute from relative position if provided
            rx = closest.get('x')
            ry = closest.get('y')
            if isinstance(rx, int) and isinstance(ry, int):
                return [rx, ry]

    # 2) pursuit_evasion: approach closest agent or attack if on same cell
    evaders = get_field(observation, 'evaders', default=None)
    if isinstance(evaders, list) and evaders:
        # pick the first evader and move towards it if within one step
        target = evaders[0]
        if isinstance(target, dict):
            tx = target.get('dx')
            ty = target.get('dy')
            if isinstance(tx, int) and isinstance(ty, int) and (abs(tx) <= 1 and abs(ty) <= 1):
                return [tx, ty]
            # Relative position
            rx = target.get('x')
            ry = target.get('y')
            if isinstance(rx, int) and isinstance(ry, int):
                dx = 0
                if rx > 0:
                    dx = 1
                elif rx < 0:
                    dx = -1
                dy = 0
                if ry > 0:
                    dy = 1
                elif ry < 0:
                    dy = -1
                if dx in (-1, 0, 1) and dy in (-1, 0, 1):
                    return [dx, dy]

    # 3) territory_control: move towards high value cells or center autonomy
    grid = get_field(observation, 'grid', default=None)
    if isinstance(grid, list) and grid:
        # If there is a 'center' or 'goal' field, bias towards it
        center = get_field(observation, 'center', default=None)
        if isinstance(center, (tuple, list)) and len(center) >= 2:
            cx, cy = int(center[0]), int(center[1])
            # choose step towards center
            dx = 0
            if cx > 0:
                dx = 1
            elif cx < 0:
                dx = -1
            dy = 0
            if cy > 0:
                dy = 1
            elif cy < 0:
                dy = -1
            if dx in (-1, 0, 1) and dy in (-1, 0, 1):
                return [dx, dy]
        # Else scan for a high-value cell if provided
        best = get_field(observation, 'best_cell', default=None)
        if isinstance(best, dict):
            bx = best.get('dx')
            by = best.get('dy')
            if isinstance(bx, int) and isinstance(by, int) and (abs(bx) <= 1 and abs(by) <= 1):
                return [bx, by]

    # Fallback: random-like deterministic choice based on observation id if available
    seed = get_field(observation, 'step', default=None)
    if isinstance(seed, int):
        # simple deterministic pattern: cycle through 4-neighborhood
        pattern = [(0,0), (1,0), (0,1), (-1,0), (0,-1)]
        idx = seed % len(pattern)
        return list(pattern[idx])

    # Final default
    return list(default_move)

